package gitrepo

import (
	"errors"
	"fmt"
	"os"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	gitfilesystem "github.com/go-git/go-git/v6/storage/filesystem"
)

// ReferenceIsAbsent requires both loose storage and the reference reader to
// establish absence. A read failure must not authorize destructive cleanup.
func ReferenceIsAbsent(repo *git.Repository, refName plumbing.ReferenceName) (bool, error) {
	if err := refName.Validate(); err != nil {
		return false, fmt.Errorf("validate reference: %w", err)
	}
	// go-git falls back to packed refs after any loose-ref read error, so its
	// not-found result alone cannot distinguish a directory from absence.
	if storage, ok := repo.Storer.(*gitfilesystem.Storage); ok {
		info, statErr := storage.Filesystem().Lstat(refName.String())
		if statErr == nil {
			if info.IsDir() {
				return false, fmt.Errorf("ref %s is a directory", refName)
			}
			return false, nil
		}
		if !errors.Is(statErr, os.ErrNotExist) {
			return false, fmt.Errorf("inspect ref %s: %w", refName, statErr)
		}
	}
	_, err := repo.Reference(refName, false)
	if errors.Is(err, plumbing.ErrReferenceNotFound) {
		return true, nil
	}
	if err != nil {
		return false, fmt.Errorf("read ref %s: %w", refName, err)
	}
	return false, nil
}
// The state directory ITSELF being a symlink is refused, not followed. Entire
// creates this directory; one that is a link is a directory it did not create
// and cannot vouch for, and following it would put session state — which commit
// linking depends on — somewhere outside the clone without anyone being told.
// `entire doctor` reports it by name.
func TestStateStore_Save_RefusesSymlinkedStateDir(t *testing.T) {
	t.Parallel()

	realDir := filepath.Join(t.TempDir(), "real-sessions")
	require.NoError(t, os.MkdirAll(realDir, 0o750))

	parent := t.TempDir()
	if err := os.Symlink(realDir, filepath.Join(parent, SessionStateDirName)); err != nil {
		t.Skipf("symlink not supported: %v", err)
	}

	store := NewStateStoreWithDir(filepath.Join(parent, SessionStateDirName))
	err := store.Save(context.Background(), &State{
		SessionID: "symlink-test", BaseCommit: "abc123", StartedAt: time.Now(),
	})
	require.ErrorIs(t, err, osroot.ErrSymlinkedPath)

	entries, readErr := os.ReadDir(realDir)
	require.NoError(t, readErr)
	assert.Empty(t, entries, "nothing may be written through the link")
}

func TestStateStore_List_EmptyDir(t *testing.T) {
	t.Parallel()

	stateDir := filepath.Join(t.TempDir(), "entire-sessions")
	require.NoError(t, os.MkdirAll(stateDir, 0o750))
	store := NewStateStoreWithDir(stateDir)

	states, err := store.List(context.Background())
	require.NoError(t, err)
	assert.Empty(t, states)
}

