#!/bin/sh
#MISE description="Run E2E canary tests with deterministic agents (no API calls)"
#USAGE arg "[filter]" help="Test name filter (regex)" default=""

set -eu

# Build entire CLI
mise run build
export E2E_ENTIRE_BIN="$PWD/entire"

# Build vogon binary
go build -o vogon ./e2e/vogon
E2E_PATH="$PWD:$PATH"

if [ -z "${E2E_ARTIFACT_DIR:-}" ]; then
  E2E_ARTIFACT_DIR="$PWD/e2e/artifacts/canary-$(date +%Y-%m-%dT%H-%M-%S)"
fi
export E2E_ARTIFACT_DIR
mkdir -p "$E2E_ARTIFACT_DIR"
echo "artifacts: $E2E_ARTIFACT_DIR"

filter="${usage_filter:-}"
vogon_rc=0
rr_rc=0

# --- vogon: runs all tests (built-in agent) ---
echo "--- canary: vogon ---"

# Preflight, mirroring the roger-roger check below: vogon registers itself only
# if its binary is on PATH when the test binary starts. Without it nothing
# registers, every test skips, and the lane exits 0 having run nothing.
if ! PATH="$E2E_PATH" command -v vogon >/dev/null 2>&1; then
  echo "error: vogon binary not found on PATH after build; the canary lane would skip every test and still report success." >&2
  exit 1
fi

PATH="$E2E_PATH" E2E_AGENT=vogon gotestsum --format dots \
  --jsonfile "$E2E_ARTIFACT_DIR/test-events-vogon.json" -- \
  -tags=e2e -count=1 -timeout=10m \
  ${filter:+-run "$filter"} \
  ./e2e/tests/... || vogon_rc=$?

go run ./e2e/cmd/testreport -color \
  -o "$E2E_ARTIFACT_DIR/report-vogon.txt" \
  "$E2E_ARTIFACT_DIR/test-events-vogon.json"

# --- roger-roger: external agent tests only (binaries from mise) ---
echo "--- canary: roger-roger ---"

# Preflight: ensure required roger-roger binaries are on PATH so tests don't silently skip
if ! command -v roger-roger >/dev/null 2>&1; then
  echo "error: roger-roger binary not found on PATH; install/configure it before running roger-roger canary tests." >&2
  exit 1
fi

if ! command -v entire-agent-roger-roger >/dev/null 2>&1; then
  echo "error: entire-agent-roger-roger binary not found on PATH; install/configure it before running roger-roger canary tests." >&2
  exit 1
fi

rr_filter="${filter:-TestExternalAgent}"
E2E_AGENT=roger-roger gotestsum --format dots \
  --jsonfile "$E2E_ARTIFACT_DIR/test-events-roger-roger.json" -- \
  -tags=e2e -count=1 -timeout=10m \
  -run "$rr_filter" \
  ./e2e/tests/... || rr_rc=$?

go run ./e2e/cmd/testreport -color \
  -o "$E2E_ARTIFACT_DIR/report-roger-roger.txt" \
  "$E2E_ARTIFACT_DIR/test-events-roger-roger.json"

echo ""
cat "$E2E_ARTIFACT_DIR/entire-version.txt" 2>/dev/null
echo "artifacts: $E2E_ARTIFACT_DIR"
if [ "$vogon_rc" -ne 0 ] || [ "$rr_rc" -ne 0 ]; then
  exit 1
fi
package agents

import (
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"testing"
)

// TestOpenCodeSeedRepoPlantsDeps runs SeedRepo the way SetupRepo does: from a
// process that never called Bootstrap.
//
// That is the whole point of the test. Bootstrap runs in `go run ./e2e/bootstrap`
// and SetupRepo in `go test ./e2e/tests`, so an implementation that hands the
// dependency tree between them through a package variable seeds nothing — and
// seeding degrades quietly, so the suite reports a fast bootstrap while every
// test still pays opencode's ~61MB per-directory install (run 33865617639).
func TestOpenCodeSeedRepoPlantsDeps(t *testing.T) {
	t.Parallel()
	if _, err := exec.LookPath(openCodeBinary); err != nil {
		t.Skip("opencode not installed")
	}
	if _, err := exec.LookPath("npm"); err != nil {
		t.Skip("npm not installed")
	}

	dir := t.TempDir()
	agent := &openCodeAgent{model: "test"}
	if err := agent.SeedRepo(dir); err != nil {
		t.Fatalf("SeedRepo: %v", err)
	}

	// node_modules is the one that matters: opencode reinstalls without it.
	//
	// Windows asserts the documented degradation instead. linkFile copies there
	// rather than linking, and a copy cannot be a 61MB directory, so SeedRepo
	// warns and leaves the repo to opencode. Everything else it plants is
	// platform-independent, which is why this branches instead of excluding the
	// whole test — the cross-process resolution above is what it exists to pin.
	link := filepath.Join(dir, ".opencode", "node_modules")
	if runtime.GOOS == "windows" {
		if _, err := os.Lstat(link); !os.IsNotExist(err) {
			t.Errorf("expected SeedRepo to degrade without node_modules on windows, got err=%v", err)
		}
	} else {
		target, err := os.Readlink(link)
		if err != nil {
			t.Fatalf("node_modules is not a symlink into the shared tree: %v", err)
		}
		if _, err := os.Stat(filepath.Join(target, "@opencode-ai", "plugin")); err != nil {
			t.Fatalf("linked tree does not contain %s: %v", openCodePluginPkg, err)
		}
	}

	for _, name := range []string{"package.json", "package-lock.json", "opencode.json"} {
		at := filepath.Join(dir, ".opencode", name)
		if name == "opencode.json" {
			at = filepath.Join(dir, name) // opencode's config sits at the root
		}
		if _, err := os.Stat(at); err != nil {
			t.Errorf("seeded %s missing: %v", name, err)
		}
	}

	// Everything planted must be invisible to git: these repos are the subject
	// of checkpoint assertions, and an untracked 61MB tree in the working set
	// would change what the CLI sees. The .gitignore names itself for that
	// reason, so a shortened list is a real regression rather than a detail.
	ignored, err := os.ReadFile(filepath.Join(dir, ".opencode", ".gitignore"))
	if err != nil {
		t.Fatalf("read seeded .gitignore: %v", err)
	}
	lines := strings.Split(string(ignored), "\n")
	for _, want := range []string{"node_modules", "package.json", "package-lock.json", ".gitignore"} {
		if !slices.Contains(lines, want) {
			t.Errorf("seeded .gitignore does not ignore %q:\n%s", want, ignored)
		}
	}
}
//go:build integration && !windows

package integration

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/execx"
)

// SIGINT to the parent must reach the plugin so it can clean up — not
// just be SIGKILL'd by the runtime. Guards both signal paths: terminal
// (via process group) and parent's context-cancel handler.
func TestExternalCommand_SigintReachesPlugin(t *testing.T) {
	t.Parallel()
	dir := t.TempDir()
	signalFile := filepath.Join(dir, "got-sigint.txt")

	// The plugin loops longer than the parent's WaitDelay+grace so that if
	// the signal path were broken, the parent would SIGKILL the child and
	// the marker would never be written. Ready-marker handshake avoids
	// racing SIGINT against shell startup before the trap is installed.
	readyFile := filepath.Join(dir, "ready.txt")
	const pluginLoopSeconds = 10 // > parent WaitDelay (5s) + grace
	body := fmt.Sprintf(
		"#!/bin/sh\ntrap 'echo trapped > %q; exit 130' INT\n"+
			"echo ready > %q\n"+
			"i=0\nwhile [ $i -lt %d ]; do sleep 0.1; i=$((i+1)); done\nexit 0\n",
		signalFile, readyFile, pluginLoopSeconds*10,
	)
	if err := os.WriteFile(filepath.Join(dir, "entire-trapint"), []byte(body), 0o755); err != nil {
		t.Fatalf("write plugin: %v", err)
	}

	cmd := execx.NonInteractive(context.Background(), getTestBinary(), "trapint")
	cmd.Env = pathWith(dir)
	var pStderr bytes.Buffer
	cmd.Stdout = &bytes.Buffer{}
	cmd.Stderr = &pStderr

	if err := cmd.Start(); err != nil {
		t.Fatalf("start: %v", err)
	}

	if !waitForFile(readyFile, 3*time.Second) {
		if killErr := cmd.Process.Kill(); killErr != nil {
			t.Logf("kill process: %v", killErr)
		}
		if waitErr := cmd.Wait(); waitErr != nil {
			t.Logf("wait after kill: %v", waitErr)
		}
		t.Fatalf("plugin never reached ready state\nparent stderr:\n%s", pStderr.String())
	}

	if err := cmd.Process.Signal(os.Interrupt); err != nil {
		t.Fatalf("signal parent: %v", err)
	}

	if !waitForFile(signalFile, 5*time.Second) {
		if waitErr := cmd.Wait(); waitErr != nil {
			t.Logf("wait after signal: %v", waitErr)
		}
		t.Fatalf("plugin never observed SIGINT — marker missing\nparent stderr:\n%s", pStderr.String())
	}
	if waitErr := cmd.Wait(); waitErr != nil {
		t.Logf("wait: %v", waitErr)
	}

	contents, err := os.ReadFile(signalFile)
	if err != nil {
		t.Fatalf("read marker: %v", err)
	}
	if got := strings.TrimSpace(string(contents)); got != "trapped" {
		t.Errorf("marker = %q, want %q", got, "trapped")
	}
}

func waitForFile(path string, timeout time.Duration) bool {
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		if _, err := os.Stat(path); err == nil {
			return true
		}
		time.Sleep(20 * time.Millisecond)
	}
	return false
}

